const { Scalekit } = require('@scalekit-sdk/node');
const fs = require('fs');

// Initialize Scalekit with environment variables
const scalekit = new Scalekit(
  process.env.SCALEKIT_ENVIRONMENT_URL,
  process.env.SCALEKIT_CLIENT_ID,
  process.env.SCALEKIT_CLIENT_SECRET
);

// Write the environment URL to the log file
fs.writeFileSync('/home/user/scalekit-init/output.log', process.env.SCALEKIT_ENVIRONMENT_URL);

console.log('Scalekit initialized successfully');
console.log('Environment URL:', process.env.SCALEKIT_ENVIRONMENT_URL);

